import type { Readable } from 'node:stream';

export interface StoredObject {
  key: string;
  lastModified: Date;
}

/**
 * Object storage used for images. Keys are always generated by the server
 * (`images/<ownerId>/<imageId>.webp`), never taken from user input.
 */
export interface StorageDriver {
  readonly name: 'local' | 's3' | 'r2';
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  /** Throws `StorageObjectNotFoundError` when the object does not exist. */
  getStream(key: string): Promise<Readable>;
  /** Idempotent: missing keys are ignored. */
  delete(keys: string[]): Promise<void>;
  exists(key: string): Promise<boolean>;
  list(prefix: string): AsyncIterable<StoredObject>;
  healthCheck(): Promise<void>;
  close?(): void;
}

export class StorageObjectNotFoundError extends Error {
  constructor(key: string) {
    super(`Stored object not found: ${key}`);
    this.name = 'StorageObjectNotFoundError';
  }
}

export const IMAGE_PREFIX = 'images/';

export const imageKeys = (ownerId: string, imageId: string) => ({
  display: `${IMAGE_PREFIX}${ownerId}/${imageId}.webp`,
  thumb: `${IMAGE_PREFIX}${ownerId}/${imageId}_thumb.webp`,
});
